  assign uio_oe = { 1'h0, \u_ctrl.miso_oe , 2'h0, \u_soc.pin_oe [2:1], \u_soc.pin_oe [5:4] };
  assign uio_out = { 1'h0, \u_ctrl.spi_miso , 2'h0, \u_soc.pin_out [2:1], \u_soc.pin_out [5:4] };
  assign { uo_out[7:3], uo_out[1:0] } = { \u_soc.u_cpu.pc [5:1], \u_ctrl.irq_n , \u_soc.pin_out [0] };
endmodule
